<?php

namespace App\Http\Controllers\Web\Packaging;

use App\Http\Controllers\Controller;
use App\Models\BatchStep;
use Illuminate\Http\Client\ConnectionException;
use Illuminate\Http\Client\PendingRequest;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Http;
use Symfony\Component\HttpFoundation\StreamedResponse;

/**
 * Read-only proxy to the PA/CSA label store.
 *
 * The labels are generated by production-automation before the sheet reaches
 * the CNC step; the MES only lists them and streams the already generated PDF.
 * Nothing here regenerates a label or touches the local label generator.
 */
class AlphacamLabelController extends Controller
{
    public function index(BatchStep $batchStep): JsonResponse
    {
        if (! $batchStep->batch_id) {
            return response()->json(['message' => __('This step is not linked to a batch.')], 422);
        }

        $config = $this->config();

        if ($config === null) {
            return response()->json(['message' => __('AlphaCAM labels are not configured.')], 503);
        }

        try {
            $response = $this->client($config)->get('/api/labels/by-batch/'.$batchStep->batch_id);
        } catch (ConnectionException) {
            return response()->json(['message' => __('AlphaCAM labels service is unreachable.')], 503);
        }

        if ($response->failed()) {
            return response()->json(['message' => __('AlphaCAM labels service returned an error.')], 502);
        }

        $sheets = collect($response->json('sheets', []))
            ->map(function ($row) use ($batchStep) {
                if (is_array($row) && isset($row['label_batch_id'])) {
                    $row['labels_pdf'] = route('packaging.labels.alphacam.pdf', [
                        'batchStep' => $batchStep,
                        'label_batch_id' => $row['label_batch_id'],
                    ]);

                    if (array_key_exists('map_pdf', $row) && $row['map_pdf'] !== null) {
                        $row['map_pdf'] = route('packaging.labels.alphacam.map', [
                            'batchStep' => $batchStep,
                            'label_batch_id' => $row['label_batch_id'],
                        ]);
                    }
                }

                return $row;
            })
            ->values()
            ->all();

        return response()->json([
            'batch_step_id' => $batchStep->id,
            'batch_id' => $batchStep->batch_id,
            'sheets' => $sheets,
        ]);
    }

    public function pdf(Request $request, BatchStep $batchStep): StreamedResponse|JsonResponse
    {
        return $this->streamPdf($request, $batchStep, 'labels.pdf');
    }

    public function map(Request $request, BatchStep $batchStep): StreamedResponse|JsonResponse
    {
        return $this->streamPdf($request, $batchStep, 'map.pdf');
    }

    private function streamPdf(Request $request, BatchStep $batchStep, string $file): StreamedResponse|JsonResponse
    {
        $labelBatchId = (string) $request->query('label_batch_id', '');

        if (! preg_match('/^[a-f0-9]{64}$/', $labelBatchId)) {
            return response()->json(['message' => __('Invalid label batch id.')], 422);
        }

        $config = $this->config();

        if ($config === null) {
            return response()->json(['message' => __('AlphaCAM labels are not configured.')], 503);
        }

        $client = $this->client($config);

        // Confirm the id really belongs to this batch before fetching the PDF:
        // the browser-supplied id must not be forwarded blindly to PA.
        try {
            $listing = $client->get('/api/labels/by-batch/'.$batchStep->batch_id);
        } catch (ConnectionException) {
            return response()->json(['message' => __('AlphaCAM labels service is unreachable.')], 503);
        }

        if ($listing->failed()) {
            return response()->json(['message' => __('AlphaCAM labels service returned an error.')], 502);
        }

        $known = collect($listing->json('sheets', []))
            ->pluck('label_batch_id')
            ->filter()
            ->contains($labelBatchId);

        if (! $known) {
            return response()->json(['message' => __('Label batch not found for this step.')], 404);
        }

        try {
            $pdf = $client->withOptions(['stream' => true])
                ->get('/api/labels/'.$labelBatchId.'/'.$file);
        } catch (ConnectionException) {
            return response()->json(['message' => __('AlphaCAM labels service is unreachable.')], 503);
        }

        if ($pdf->status() === 404) {
            $message = $file === 'map.pdf'
                ? __('Sheet map PDF not found.')
                : __('Label PDF not found.');

            return response()->json(['message' => $message], 404);
        }

        if ($pdf->failed()) {
            return response()->json(['message' => __('AlphaCAM labels service returned an error.')], 502);
        }

        $body = $pdf->toPsrResponse()->getBody();
        $prefix = $file === 'map.pdf' ? 'map' : 'labels';
        $filename = $prefix.'-'.$batchStep->batch_id.'-'.$labelBatchId.'.pdf';

        return response()->stream(function () use ($body) {
            while (! $body->eof()) {
                echo $body->read(8192);
            }
        }, 200, [
            'Content-Type' => 'application/pdf',
            'Content-Disposition' => 'inline; filename="'.$filename.'"',
        ]);
    }

    /** @return array{base_url:string,token:string,timeout:float}|null */
    private function config(): ?array
    {
        $baseUrl = trim((string) config('packaging.alphacam_labels.base_url'));
        $token = (string) config('packaging.alphacam_labels.token');

        if ($baseUrl === '' || $token === '') {
            return null;
        }

        return [
            'base_url' => rtrim($baseUrl, '/'),
            'token' => $token,
            'timeout' => (float) config('packaging.alphacam_labels.timeout', 5.0),
        ];
    }

    /** @param  array{base_url:string,token:string,timeout:float}  $config */
    private function client(array $config): PendingRequest
    {
        return Http::withToken($config['token'])
            ->timeout($config['timeout'])
            ->acceptJson()
            ->baseUrl($config['base_url']);
    }
}
